// Decide qué facturas vencidas reciben gestión hoy y con qué tono. Sin estado ni base de datos.
// Calendario de cobro: días de mora en los que toca recordatorio. Cámbialo aquí si tu política es otra.
const CALENDARIO = {
  amable: [1, 7],
  firme: [15, 22],
  escalarDesde: 30, // desde este día de mora se escala al responsable…
  escalarCada: 7, // …y se repite cada tantos días
};
// Cambia MONEDA si facturas en otra moneda (por ejemplo 'USD' o 'MXN'): solo afecta al formato del correo.
const MONEDA = 'COP';
const LOCALE = 'es-CO';

const hoy = $now.startOf('day');
// El flujo corre de lunes a viernes. Los lunes revisa también el sábado y el domingo (ventana de 3 días)
// para no perder recordatorios ni escalamientos que cayeron en fin de semana. Los demás días, solo hoy.
const ventana = hoy.weekday === 1 ? 3 : 1;

// Vencimiento → fecha. Acepta el número de serie de Sheets (celda de fecha real: «Leer facturas» la entrega así,
// sin depender del idioma de la hoja) y texto AAAA-MM-DD o DD/MM/AAAA.
function fecha(valor) {
  if (typeof valor === 'number') {
    return DateTime.fromObject({ year: 1899, month: 12, day: 30 }).plus({ days: Math.floor(valor) });
  }
  const texto = String(valor ?? '').trim();
  const dma = texto.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (dma) return DateTime.fromObject({ year: +dma[3], month: +dma[2], day: +dma[1] });
  return DateTime.fromISO(texto.slice(0, 10));
}

// Etapa que corresponde a un día de mora exacto, o null si ese día no toca recordatorio
function etapaDelDia(dia) {
  if (CALENDARIO.amable.includes(dia)) return 'amable';
  if (CALENDARIO.firme.includes(dia)) return 'firme';
  if (dia >= CALENDARIO.escalarDesde && (dia - CALENDARIO.escalarDesde) % CALENDARIO.escalarCada === 0) return 'escalar';
  return null;
}

// Revisa los días de mora de la ventana (hoy y, si es lunes, el sábado y el domingo).
// Si varios tocan recordatorio, gana el día más alto.
function etapaEnVentana(diasHoy) {
  for (let dia = diasHoy; dia > diasHoy - ventana; dia--) {
    if (dia < 1) break;
    const etapa = etapaDelDia(dia);
    if (etapa) return etapa;
  }
  return null;
}

// Monto → número. Los números se usan tal cual; el texto se lee con formato colombiano
// («$ 1.500.000», «1.500.000», «1500000», «1.500.000,50»). Si no se puede leer, devuelve null.
function aNumero(valor) {
  if (typeof valor === 'number') return Number.isFinite(valor) ? valor : null;
  const limpio = String(valor ?? '').replace(/\$/g, '').replace(/\s/g, '').replace(/\./g, '').replace(',', '.');
  if (limpio === '') return null;
  const n = Number(limpio);
  return Number.isFinite(n) ? n : null;
}
const dinero = (n) => (n === null ? 'el monto pendiente' : new Intl.NumberFormat(LOCALE, { style: 'currency', currency: MONEDA, maximumFractionDigits: 0 }).format(n));

const esCorreo = (texto) => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(texto);
const ACCIONES = { amable: 'Recordatorio amable', firme: 'Recordatorio firme', escalar: 'Escalado al responsable' };

const salida = [];
for (const { json: f } of $input.all()) {
  const estado = String(f.Estado ?? '').trim().toLowerCase();
  if (!f['Número'] || estado.startsWith('pagad')) continue;
  const vence = fecha(f.Vencimiento);
  if (!vence.isValid) continue;
  const dias = Math.round(hoy.diff(vence.startOf('day'), 'days').days);
  const tono = etapaEnVentana(dias);
  if (!tono) continue;

  const correo = String(f.Correo ?? '').trim();
  const responsable = String(f.Responsable ?? '').trim();
  // Quién debe tener un correo válido: «amable» el cliente; «firme» el cliente (el responsable va en copia
  // solo si es válido); «escalar» el responsable, que es el destinatario.
  const sinCorreo = tono === 'escalar' ? !esCorreo(responsable) : !esCorreo(correo);
  const conCopia = tono === 'firme' && esCorreo(responsable);
  let accion = ACCIONES[tono];
  if (sinCorreo) accion = 'Sin correo válido: no se envió';
  else if (tono === 'firme' && !conCopia) accion = 'Recordatorio firme (sin copia: el responsable no tiene un correo válido)';

  salida.push({
    json: {
      numero: String(f['Número']),
      cliente: f.Cliente,
      correo,
      responsable,
      cc: conCopia ? responsable : '',
      monto: dinero(aNumero(f.Monto)),
      vencimiento: vence.setLocale('es').toFormat("d 'de' LLLL"),
      dias,
      // «sin_correo» sale por su propia salida del Switch: no se envía nada y se registra para corregirlo
      etapa: sinCorreo ? 'sin_correo' : tono,
      accion,
    },
  });
}
return salida;
